'use strict';
const REPLAY_PAIRS=[[0,4],[1,5],[2,6],[3,7]];
let scenarioVariant='near',scenarioKickRole='MT';
function prepareCloneMemories(){const memories=Object.fromEntries(roles.map(role=>[role,[]]));const remember=(role,type)=>{if(memories[role])memories[role].push(type)};if(resolution.jump)remember(resolution.jump.role,'boss');const defams=resolution.events.find(e=>e.key==='defams');for(const role of defams?.targets||[])remember(role,'defam');for(const stack of resolution.events.find(e=>e.key==='stack')?.stacks||[])remember(stack.owner,'stack');for(const cone of resolution.events.find(e=>e.key==='cones')?.cones||[])remember(cone.owner,'cone');resolution.cloneMemories=memories;return memories}
function behindTarget(p){const boss=resolution.boss,a=resolution.cleave?.angle??resolution.bossHeading??0,offset=(roles.indexOf(p.role)-3.5)*6;return{x:boss.x+Math.sin(a)*90+Math.cos(a)*offset,y:boss.y+Math.cos(a)*90-Math.sin(a)*offset,r:26}}
function northReplayTarget(role){if(resolution.raySlots[role]){const old=resolution.raySlots[role],x=Math.sign(old.x)*(Math.abs(old.x)>100?200:105);return{x,y:-Math.sqrt(410*410-x*x),r:28}};const peers=party.filter(p=>groupOf(p.role)===groupOf(role)).sort((a,b)=>a.clock-b.clock),index=peers.findIndex(p=>p.role===role),x=[-200,-105,105,200][Math.max(0,index)];return{x,y:-Math.sqrt(410*410-x*x),r:28}}
function netherPairTarget(p){const sign=groupOf(p.role)==='green'?1:-1,primary=hasMechanic(p.role,'defam'),variant=resolution.netherVariant;const distance=variant==='near'?(primary?105:140):variant==='far'?(primary?275:238):(primary?170:205);return{x:resolution.boss.x+sign*distance,y:resolution.boss.y,r:22}}
function replayStackSide(role){return ['MT','OT','M1','M2'].includes(role)?'right':'left'}
function cloneStackTarget(p){const sign=replayStackSide(p.role)==='right'?1:-1,peers=party.filter(q=>replayStackSide(q.role)===replayStackSide(p.role)).sort((a,b)=>roles.indexOf(a.role)-roles.indexOf(b.role)),i=Math.max(0,peers.findIndex(q=>q.role===p.role));return{x:sign*325+[-13,13,-13,13][i],y:[-13,-13,13,13][i],r:28}}
function extendedTarget(p){const t=phaseTime();if(t<COMBAT.kickMove)return null;if(t<COMBAT.reenact)return behindTarget(p);if(t<=COMBAT.replayRays+.1)return resolution.rayTargets.includes(p.role)?northReplayTarget(p.role):netherPairTarget(p);if(t<=COMBAT.replayCone1+.1&&replayStackSide(p.role)==='left')return{x:-8*REP1_SCALE,y:-16*REP1_SCALE,r:28};if(t<=COMBAT.wave2+.1||replayStackSide(p.role)==='left')return cloneStackTarget(p);return northReplayTarget(p.role)}
function resolveNetherwrath(){const near=resolution.netherVariant==='near',origin=resolution.boss,ordered=[...party].sort((a,b)=>(dist(actor(a.role),origin)-dist(actor(b.role),origin))*(near?1:-1)||roles.indexOf(a.role)-roles.indexOf(b.role)),targets=ordered.slice(0,2).map(p=>p.role),stacks=[],hitCounts=Object.fromEntries(roles.map(r=>[r,0]));for(const role of targets){const center=actor(role),members=party.filter(p=>dist(actor(p.role),center)<=GEOMETRY.nether).map(p=>p.role);effect('nether',center,{radius:GEOMETRY.nether,owner:role},1.25);stacks.push({target:role,members});for(const member of members)hitCounts[member]++;validateStackGroup(members,roles.filter(r=>groupOf(r)===groupOf(role)&&!resolution.rayTargets.includes(r)),2,combatError,`Netherwrath ${near?'Near':'Far'}`)}for(const role of roles){if(!resolution.rayTargets.includes(role)&&hitCounts[role]===0)combatError([role],'Netherwrath : tu n’as rejoint aucun partage à deux.');if(hitCounts[role]>1)combatError([role],'Netherwrath : touché par les deux stacks.');if(hitCounts[role]&&resolution.rayTargets.includes(role))combatError([role],'Netherwrath : un porteur de rayon a aussi pris un stack de proximité.')}return{variant:resolution.netherVariant,targets,stacks,hitCounts}}
function replayClones(index,phase='all'){const pair=REPLAY_PAIRS[index],activated=[],rays=[];for(const p of party.filter(p=>pair.includes(p.clock))){const origin=pt(p.clock*TAU/8,325),memories=resolution.cloneMemories[p.role]||[];activated.push({role:p.role,clock:p.clock,mark:marks[p.clock],mechanics:[...memories]});for(const type of memories){if(phase!=='all'&&type!==(phase==='landing'||phase==='rays'?'boss':phase))continue;if(type==='boss'){
 if(phase!=='rays'){effect('landing',origin,{radius:GEOMETRY.landing,owner:'Clone '+marks[p.clock]},.9);const landed=party.filter(q=>dist(actor(q.role),origin)<=GEOMETRY.landing+GEOMETRY.player).map(q=>q.role);if(landed.length)combatError(landed,'Firefall Splash du clone : trop près du clone lors du saut.');}if(phase!=='landing'){const hitCount=Object.fromEntries(roles.map(r=>[r,0]));for(const role of resolution.rayTargets){const angle=facingToward(origin,actor(role));effect('ray',origin,{angle,half:GEOMETRY.rayHalf,range:GEOMETRY.range,owner:role},1.25);rays.push({target:role,fromClock:p.clock});const clipped=roles.filter(r=>r!==role&&inCone(actor(r),origin,angle,GEOMETRY.rayHalf));if(clipped.length)combatError([role,...clipped],`Rayon attiré par ${role} : il touche un autre joueur.`);for(const q of party)if(inCone(actor(q.role),origin,angle,GEOMETRY.rayHalf))hitCount[q.role]++}for(const role of roles)if(hitCount[role]>(resolution.rayTargets.includes(role)?1:0))combatError([role],'Scalding Waves du clone : touché par un rayon supplémentaire.');}
 }else if(type==='defam'){effect('defam',origin,{radius:GEOMETRY.defam,owner:'Clone '+marks[p.clock]},1.2);const clipped=party.filter(q=>dist(actor(q.role),origin)<=GEOMETRY.defam+GEOMETRY.player).map(q=>q.role);if(clipped.length)combatError(clipped,`Mana Burst du clone ${marks[p.clock]} : reste hors de la défamation.`);
 }else if(type==='stack'){effect('stack',origin,{radius:GEOMETRY.stack,owner:'Clone '+marks[p.clock]},1);const members=party.filter(q=>dist(actor(q.role),origin)<=GEOMETRY.stack).map(q=>q.role);const side=origin.x>0?'right':'left',expected=roles.filter(role=>replayStackSide(role)===side);validateStackGroup(members,expected,4,combatError,`Heavy Slam du clone ${marks[p.clock]} · ${side==='right'?'droite':'gauche'}`);activated.at(-1).members=members;activated.at(-1).stackSide=side;
 }else if(type==='cone'){const angle=facingToward(origin,{x:0,y:0});effect('cone',origin,{angle,half:GEOMETRY.coneHalf,range:GEOMETRY.range,owner:'Clone '+marks[p.clock]},1.2);const clipped=party.filter(q=>inCone(actor(q.role),origin,angle)).map(q=>q.role);if(clipped.length)combatError(clipped,`Projection du clone ${marks[p.clock]} : cône orienté vers le centre.`)}
 }}resolution.activeWave={index,pair:[...pair],at:time};return{pair:[...pair],activated,rays}}
function fireExtendedEvent(key,before){if(['replayLanding','replayRays','replayCone1','replayCone3'].includes(key)){const index=key==='replayCone1'?1:key==='replayCone3'?3:0,phase=key==='replayLanding'?'landing':key==='replayRays'?'rays':'cone',data=replayClones(index,phase);eventResult(key,'Reconstitution · '+(phase==='landing'?'saut':phase==='rays'?'rayons':'cône'),before,data);return true}if(key==='kickTell'){const role=scenarioKickRole,angle=facingToward(resolution.boss,actor(role));resolution.cleave={target:role,angle};resolution.bossHeading=angle;eventResult(key,'Snaking Kick · direction figée',before,{target:role,angle});return true}if(key==='kick'){const angle=resolution.cleave?.angle??0;effect('cleave',resolution.boss,{angle,half:Math.PI/2,range:GEOMETRY.range},1.2);const hits=party.filter(p=>inCone(actor(p.role),resolution.boss,angle,Math.PI/2)).map(p=>p.role);if(hits.length)combatError(hits,'Snaking Kick : passe derrière le boss, sa direction est figée.');eventResult(key,'Snaking Kick',before,{hits,angle});return true}if(key==='reenact'){prepareCloneMemories();eventResult(key,'Reconstitution · mémoire des huit clones',before,{order:REPLAY_PAIRS.map(pair=>pair.map(clock=>marks[clock]))});return true}if(key==='netherTell'){resolution.netherVariant=scenarioVariant;eventResult(key,`Netherwrath ${scenarioVariant==='near'?'Near · Proche':'Far · Éloigné'}`,before,{variant:scenarioVariant});return true}if(/^wave[0-3]$/.test(key)){const index=Number(key.at(-1)),nether=index===0?resolveNetherwrath():null,data=replayClones(index,index===2?'stack':'defam');eventResult(key,`Reconstitution ${data.pair.map(c=>marks[c]).join(' / ')}${nether?' + Netherwrath '+(nether.variant==='near'?'Near':'Far'):''}`,before,{...data,nether});return true}return false}
function drawReconstitution(){if(mode!=='placement'||!resolution.locked)return;if(phaseTime()>=COMBAT.cones&&phaseTime()<COMBAT.kick&&guide){ctx.save();ctx.beginPath();ctx.arc(0,0,478.125,0,TAU);ctx.clip();drawSector(resolution.boss,resolution.cleave?.angle??0,Math.PI/2,GEOMETRY.range,'#cf364c30','#ef7c9166');ctx.restore();text('DIRECTION FIGÉE',resolution.boss.x,resolution.boss.y+100,10,'#ffc4bd')}
 if(phaseTime()<COMBAT.reenact)return;for(const p of party){const origin=pt(p.clock*TAU/8,325),memories=resolution.cloneMemories[p.role]||[];if(resolution.activeWave&&time-resolution.activeWave.at<1.5&&resolution.activeWave.pair.includes(p.clock))circle(origin.x,origin.y,34,'#b2a4ff2b','#d3baff',2);if(guide)for(let i=0;i<memories.length;i++){const type=memories[i],x=origin.x+(i-(memories.length-1)/2)*35,y=origin.y-33;ctx.save();ctx.translate(x,y);ctx.scale(.55,.55);if(type==='boss'){circle(0,0,27,'#183b4bee','#a5ddfa',1.5);for(const dx of [-15,-5,5,15])line({x:0,y:13},{x:dx,y:-16},'#d2eeff',2)}else icon(type,0,0,28);ctx.restore()}}
 if(phaseTime()>=COMBAT.netherTell&&phaseTime()<COMBAT.wave0&&guide){const variant=resolution.netherVariant;for(const p of party.filter(p=>!resolution.rayTargets.includes(p.role))){const target=netherPairTarget(p);circle(target.x,target.y,8,'#a8c5ff33','#b2baff',1)}text(`NETHERWRATH ${variant==='near'?'NEAR · PROCHE':'FAR · ÉLOIGNÉ'}`,0,65,13,'#c8c3ff','700')}
}
